    /// <summary>
    /// Optimized lookup sets for code validation (lazily initialized on first access).
    /// </summary>
    private static readonly Dictionary<string, HashSet<string>> _validationSets = new(StringComparer.Ordinal);

    /// <inheritdoc/>
    public IReadOnlyList<FhirCode>? GetCodes(string valueSetUrl)
    {
        ArgumentNullException.ThrowIfNull(valueSetUrl);
        var normalized = NormalizeUrl(valueSetUrl);
        return _valueSets.TryGetValue(normalized, out var codes) ? codes : null;
    }

    /// <inheritdoc/>
    public bool IsKnownValueSet(string valueSetUrl)
    {
        ArgumentNullException.ThrowIfNull(valueSetUrl);
        return _valueSets.ContainsKey(NormalizeUrl(valueSetUrl));
    }

    /// <inheritdoc/>
    public bool? IsValidCode(string valueSetUrl, string code)
    {
        ArgumentNullException.ThrowIfNull(valueSetUrl);
        ArgumentNullException.ThrowIfNull(code);

        var normalized = NormalizeUrl(valueSetUrl);

        // Lazy initialize validation set for this valueSetUrl
        if (!_validationSets.TryGetValue(normalized, out var validCodes))
        {
            // Check if we have this valueset
            if (!_valueSets.TryGetValue(normalized, out var codes))
            {
                return null;
            }

            // Build validation set on-demand
            validCodes = codes.Select(static c => c.Code).ToHashSet(StringComparer.Ordinal);
            _validationSets[normalized] = validCodes;
        }

        return validCodes.Contains(code);
    }

    /// <summary>
    /// Normalizes a ValueSet URL by removing version suffix after '|'.
    /// </summary>
    /// <param name="url">The URL to normalize.</param>
    /// <returns>The normalized URL without version suffix.</returns>
    private static string NormalizeUrl(string url)
    {
        var pipeIndex = url.IndexOf('|', StringComparison.Ordinal);
        return pipeIndex > 0 ? url[..pipeIndex] : url;
    }
